"use client";

import * as React from "react";
import { motion } from "motion/react";
import { cn } from "@/lib/utils";
import { useChoreography } from "@/lib/cojeev-motion/choreography";
import { AnimatedIcon } from "@/components/ui/animated-icon";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Empty, EmptyDescription, EmptyTitle } from "@/components/ui/empty";
import { Stepper, StepperIndicator, StepperItem, StepperList, StepperTitle } from "@/components/ui/stepper";
import { BodySecondary, Meta, Title } from "@/components/ui/typography";

export type MilestoneState = "complete" | "current" | "upcoming";
export type Milestone = {
  /** Stable identity, independent of display text and array position. */
  id: string;
  title: React.ReactNode;
  description?: React.ReactNode;
  state: MilestoneState;
  meta?: React.ReactNode;
  /** Disables the optional selection button; does not change progress. */
  disabled?: boolean;
};
export type MilestonePathProps = Omit<React.ComponentProps<"section">, "children" | "title"> & {
  /** Ordered journey. Supply at most one current milestone. */
  items: readonly Milestone[];
  title?: React.ReactNode;
  description?: React.ReactNode;
  empty?: React.ReactNode;
  statusLabels?: Partial<Record<MilestoneState, React.ReactNode>>;
  /** Makes titles native buttons. Progress remains owned by the caller. */
  onMilestoneSelect?: (id: string) => void;
};

const stateLabels: Record<MilestoneState, string> = {
  complete: "Completed",
  current: "In progress",
  upcoming: "Upcoming",
};
const connection = "M18 0 C18 26 21 31 18 50 C15 69 18 75 18 100";

export function MilestonePath({
  items, title, description, empty, statusLabels, onMilestoneSelect,
  className, "aria-label": ariaLabel, "aria-labelledby": labelledBy, ...props
}: MilestonePathProps) {
  const titleId = React.useId();
  const { quiet, transition } = useChoreography();
  const currentIndex = items.findIndex(item => item.state === "current");
  const upcomingIndex = items.findIndex(item => item.state === "upcoming");
  // One terminal provider slot represents a finished journey without a fake
  // current item. Per-item states remain authoritative for mixed histories.
  const position = currentIndex >= 0 ? currentIndex + 1 : upcomingIndex >= 0 ? upcomingIndex + 1 : items.length + 1;
  return <section {...props} data-slot="milestone-path" data-motion-quiet={quiet || undefined}
    aria-label={ariaLabel ?? (!title && !labelledBy ? "Milestones" : undefined)}
    aria-labelledby={labelledBy ?? (title ? titleId : undefined)}
    className={cn("v-milestone-path", className)}>
    {(title || description) && <header className="v-milestone-path__header">
      {title && <Title id={titleId}>{title}</Title>}
      {description && <BodySecondary as="div">{description}</BodySecondary>}
    </header>}
    {items.length === 0 ? empty ?? <Empty>
      <EmptyTitle>No milestones yet</EmptyTitle>
      <EmptyDescription>Add the steps that matter to this journey.</EmptyDescription>
    </Empty> : <Stepper value={position} count={items.length + 1}>
      <StepperList className="v-milestone-path__list" role="list" data-no-glide="">
      {items.map((item, index) => <StepperItem key={item.id} step={index + 1} data-milestone-id={item.id}
        data-state={item.state} aria-current={item.state === "current" ? "step" : undefined}
        className="v-milestone-path__item">
        {index < items.length - 1 && <svg aria-hidden="true" className="v-milestone-path__connection"
          viewBox="0 0 36 100" preserveAspectRatio="none" fill="none">
          <path d={connection} className="v-milestone-path__track" vectorEffect="non-scaling-stroke" />
          <motion.path d={connection} className="v-milestone-path__progress" vectorEffect="non-scaling-stroke"
            initial={false} animate={{ pathLength: item.state === "complete" ? 1 : 0 }}
            transition={quiet ? { duration: 0 } : transition} />
        </svg>}
        <StepperIndicator step={index + 1} className="v-milestone-path__marker" aria-hidden="true">
          {item.state === "complete" ? <AnimatedIcon name="check" preset="validation" size="sm" /> : <span>{index + 1}</span>}
        </StepperIndicator>
        <div className="v-milestone-path__content">
          <div className="v-milestone-path__heading">
            <StepperTitle className="v-milestone-path__title">{onMilestoneSelect ? <Button variant="ghost" size="sm" disabled={item.disabled}
              className="v-milestone-path__select" onClick={() => onMilestoneSelect(item.id)}>
              {item.title}
            </Button> : item.title}</StepperTitle>
            <Badge size="sm" variant={item.state === "complete" ? "olive-soft" : item.state === "current" ? "pink-soft" : "cream"}
              className="v-milestone-path__status">{statusLabels?.[item.state] ?? stateLabels[item.state]}</Badge>
          </div>
          {item.description && <BodySecondary as="div" className="v-milestone-path__description">{item.description}</BodySecondary>}
          {item.meta && <Meta className="v-milestone-path__meta">{item.meta}</Meta>}
        </div>
      </StepperItem>)}
      </StepperList>
    </Stepper>}
  </section>;
}

@layer cojeev-states {
.v-milestone-path[data-slot] { min-width:0; width:100%; color:var(--v-text); }
.v-milestone-path__header { display:grid; gap:8px; margin-block-end:28px; }
.v-milestone-path__header :is(h3,p) { margin:0; }
.v-milestone-path[data-slot] .v-milestone-path__list { display:grid; margin:0; padding:0; list-style:none; }
.v-milestone-path[data-slot] .v-milestone-path__item { position:relative; display:grid; grid-template-columns:36px minmax(0,1fr); align-items:start; column-gap:18px; min-width:0; padding-block:0 30px; }
.v-milestone-path__item:last-child { padding-block-end:0; }
.v-milestone-path__item::marker { content:none; }
.v-milestone-path[data-slot] .v-milestone-path__item::before { display:none; }
.v-milestone-path[data-slot] .v-milestone-path__marker { position:relative; z-index:1; display:grid; place-items:center; inline-size:36px; block-size:36px; border-radius:45% 55% 51% 49% / 50% 46% 54% 50%; background:var(--card); box-shadow:inset 0 0 0 1.5px var(--v-edge); color:var(--v-text-2); font-size:13px; font-weight:600; font-variant-numeric:tabular-nums; }
.v-milestone-path[data-slot] .v-milestone-path__item[data-state="complete"] .v-milestone-path__marker { background:var(--v-olive); color:var(--v-on-accent); box-shadow:none; }
.v-milestone-path[data-slot] .v-milestone-path__item[data-state="current"] .v-milestone-path__marker { background:var(--v-pink); color:var(--v-on-accent); box-shadow:0 0 0 5px color-mix(in oklab,var(--v-pink) 18%,transparent); }
.v-milestone-path__connection { position:absolute; pointer-events:none; inset-inline-start:0; inset-block-start:24px; inline-size:36px; block-size:calc(100% - 13px); overflow:visible; }
.v-milestone-path__connection path { stroke-width:2; stroke-linecap:round; }
.v-milestone-path__track { stroke:var(--v-edge); }
.v-milestone-path__progress { stroke:var(--v-olive); }
.v-milestone-path__content { display:grid; align-content:start; gap:8px; min-width:0; padding-block-start:5px; }
.v-milestone-path__heading { display:flex; align-items:center; flex-wrap:wrap; gap:8px 12px; min-width:0; }
.v-milestone-path[data-slot] .v-milestone-path__title { flex:1 1 14rem; min-width:0; font-size:16px; font-weight:600; line-height:1.45; color:var(--v-text); overflow-wrap:anywhere; }
.v-milestone-path__select[data-slot] { min-height:32px; height:auto; padding:3px 8px; margin-inline-start:-8px; font-size:16px; line-height:1.45; white-space:normal; text-align:start; justify-content:flex-start; max-width:100%; overflow-wrap:anywhere; }
.v-milestone-path__status[data-slot] { flex-shrink:0; max-width:100%; height:auto; min-height:20px; padding-block:3px; white-space:normal; line-height:1.2; }
.v-milestone-path__description[data-slot] { max-width:62ch; overflow-wrap:anywhere; line-height:1.55; }
.v-milestone-path__meta[data-slot] { overflow-wrap:anywhere; }
.v-milestone-path__description :first-child { margin-block-start:0; }
.v-milestone-path__description :last-child { margin-block-end:0; }
@media(max-width:480px) { .v-milestone-path[data-slot] .v-milestone-path__item { column-gap:13px; padding-block-end:26px; } .v-milestone-path__heading { gap:7px 10px; } }
.v-milestone-path[data-slot] .v-milestone-path__item:last-child { padding-block-end:0; }

}
